{"function":"() => {
const out=[];
const sel='label,legend,p,h1,h2,a,button,input,textarea,th,td,span,.table-title';
const lum=c=>{const m=c.match(/[\d.]+/g).map(Number);const [r,g,b]=m.slice(0,3).map(v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)});return [0.2126*r+0.7152*g+0.0722*b,m[3]===undefined?1:m[3]]};
function bg(e){while(e){const c=getComputedStyle(e).backgroundColor;const m=c.match(/[\d.]+/g);if(m&&(m[3]===undefined||+m[3]>0))return c;e=e.parentElement}return 'rgb(255,255,255)'}
document.querySelectorAll(sel).forEach(e=>{if(!e.childNodes.length)return;const t=[...e.childNodes].filter(n=>n.nodeType==3&&n.textContent.trim()).map(n=>n.textContent.trim()).join(' ');if(!t&&!/INPUT|TEXTAREA/.test(e.tagName))return;const s=getComputedStyle(e);const r=e.getBoundingClientRect();if(!r.width)return;const l1=lum(s.color)[0],l2=lum(bg(e))[0];const cr=(Math.max(l1,l2)+.05)/(Math.min(l1,l2)+.05);out.push([e.tagName,e.className,e.id,t.slice(0,30),s.color,bg(e),s.fontSize,s.fontWeight,cr.toFixed(2),Math.round(r.width)+'x'+Math.round(r.height)])});
return out.filter(o=>+o[8]<5.5||true).map(o=>o.join('|')).join('\n')}"}

